  insert into projects (slug, title, category, kind_label, image_url, sort, featured, published)
  select slug, title, category, kind_label, image_url, sort, featured, true from v where image_url is not null
  on conflict (slug) do update set title = excluded.title, category = excluded.category, kind_label = excluded.kind_label,
    image_url = excluded.image_url, sort = excluded.sort, featured = excluded.featured, published = true
